        let operationIdArg = args[0] as! String
        do {
          try api.cancelExport(operationId: operationIdArg)
          reply(wrapResult(nil))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      cancelExportChannel.setMessageHandler(nil)
    }
  }
}
